# Competency 1 (part B): skills 1.5 SLA theories, 1.6 L2 development, 1.7 sociolinguistics.
# Writes c1b.json next to this file.


def T(code, note, pair=None):
    d = {"code": code, "note": note}
    if pair:
        d["pair"] = pair
    return d


def Q(id, type, difficulty, stem, options, answer, why, traps, key, stimulus=None, diag=0):
    d = {"id": id, "skill": id.split("-")[0], "type": type, "difficulty": difficulty, "diag": diag}
    if stimulus:
        d["stimulus"] = stimulus
    d.update({"stem": stem, "options": options, "answer": answer, "why": why, "traps": traps, "key": key})
    return d


